  public static void adminEditDigitalHuman(RoutingContext ctx, WebClient webClient) {
    AdminEditDigitalHumanRequest request = getProto(ctx);
    PictureInQuery avatarInQuery = uploadAvatar(request.getAvatar());
    log.info("adminEditDigitalHuman userId={}", request.getUserId());
    List<InterestTab> interests = request.getInterestsList();
    User user =
        User.newBuilder()
            .setUserId(request.getUserId())
            .setUsername(request.getUsername())
            .setGender(request.getGender())
            .setBio(request.getBio())
            .setAge(request.getAge())
            .setCustomAvatar(avatarInQuery)
            .setProfession(request.getProfession())
            .setAvatarId(request.getAvatarId())
            .setEducation(request.getEducation())
            .setRace(request.getRace())
            .setGeoLocation(request.getGeoLocation())
            .setIsVideoTest(request.getIsPwaVideoVerify())
            .build();
    try {

      try {
        // 处理pwa审核判罚状态
        if (request.getIsPwaVideoVerify()) {
          PwaStatusService.unAuditPenalty(request.getUserId());
        } else {
          PwaStatusService.setAuditPenalty(request.getUserId());
        }
      } catch (Exception e) {
        log.error("Deal AuditPenalty userid:{} error {}", request.getUserId(), e.getMessage(), e);
      }

      user = UserDBUtils.adminUpdateUser(user);
      if (user == null) {
        end(ctx, AdminEditDigitalHumanResponse.newBuilder().setCode(UserServiceCommonCode.Failed));
        return;
      }
      await(UserInterestService.editUserTextTags(user.getUserId(), interests));
      user = user.toBuilder().addAllInterestTabs(interests).build();
      AdminUserInfo adminUserInfo = toAdminUserInfo(user);
      end(
          ctx,
          AdminEditDigitalHumanResponse.newBuilder()
              .setCode(UserServiceCommonCode.Success)
              .setUserInfo(adminUserInfo));
      UserCacheService.SINGLETON.resetUser(user.getUserId());
      log.info(
          "adminEditDigitalHuman userId={}, updateUserPhotoStyle, fileName={}",
          request.getUserId(),
          request.getAvatar().getName());
        updateUserFaceScoreAndStyle(
                webClient,
                request.getUserId(),
                request.getAvatar().getFile().toByteArray(),
                request.getAvatar().getName());
    } catch (Exception e) {
      endException(ctx, e);
    }
  }

